#!/usr/bin/env node
/**
 * Copies the committed, public-safe OpenAPI spec into public/openapi.json so
 * lemma.work/openapi.json serves it as a static file.
 *
 * The source of truth is lemma-python/lemma_sdk/openapi_spec.json — the same
 * spec `pip install lemma-sdk` ships, already stripped of internal-only
 * operations (billing, the job scheduler, inbound webhook receivers) by
 * scripts/prepare_client_openapi.py and regenerated by
 * lemma-python/scripts/generate_openapi_client.sh. Publishing it here makes
 * something already public (it is inside a published PyPI package, in an
 * open-source repo) reachable at the URL an agent actually looks for it at,
 * rather than exposing anything new.
 *
 * The Docker build context for this app does not include lemma-python/ (see
 * ../Dockerfile), so this can only run where the sibling checkout exists —
 * i.e. local dev and CI. That is fine: the committed public/openapi.json is
 * the artifact that ships, and this script's job is keeping it in sync
 * whenever a maintainer regenerates the spec. It no-ops, rather than fails,
 * when the source tree is not there.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = join(root, "..", "lemma-python", "lemma_sdk", "openapi_spec.json");
const outPath = join(root, "public", "openapi.json");

if (!existsSync(sourcePath)) {
  console.log(`[openapi] ${sourcePath} not found, leaving public/openapi.json as-is`);
  process.exit(0);
}

const spec = JSON.parse(readFileSync(sourcePath, "utf-8"));

// The committed spec has no `servers` entry — the generated clients take
// their base URL from LemmaClient({ apiUrl }) instead. The published copy is
// read by agents with no client to configure, so it needs to say where the
// API actually lives.
if (!spec.servers || spec.servers.length === 0) {
  spec.servers = [{ url: "https://api.lemma.work", description: "Lemma Cloud API" }];
}

writeFileSync(outPath, `${JSON.stringify(spec, null, 2)}\n`);
console.log(`[openapi] wrote ${outPath} (${Object.keys(spec.paths ?? {}).length} paths)`);
